clear
%%
%[text] Motor control response
num = [0 0 0.01] %[output:20e3d39d]
den = [0.005 0.06 0.1001] %[output:8c8ebc60]

kp0 = 1;
ki0 = 1;
kd0 = 0;

[S,closedLoop] = motorResponse(num,den,kp0,ki0,kd0) %[output:426e2203] %[output:03854155]

step(closedLoop) %[output:7e03f288]

%%
%[text] Unconstrained optimization
% Set up the optimization
P0 = [kp0 ki0 kd0];
optimFunc = @(P) objFunc(P,num,den);
lb = [0 0 0];
ub = [1 1 1]*1e2;

% Do a pattern search
tic
[P,fval] = patternsearch(optimFunc,P0,[],[],[],[],lb,ub)
toc
%%
% Look at the result
[S,closedLoop] = motorResponse(num,den,P(1),P(2),P(3)) %[output:691d43b6] %[output:1ec2e91b]
closedLoop %[output:85e494dd]
step(closedLoop) %[output:3652cbc6]
%%
%%
%[text] ## Help us Improve
%[text] [Share your feedback](<matlab: ShareFeedback>) to help us improve this module.
function [obj] = objFunc(P,num,den)
    [S,~] = motorResponse(num,den,P(1),P(2),P(3));
    obj = S.RiseTime^2 + S.SettlingTime^2 + S.Overshoot^2 + 1000*(S.Peak-1)^2;
end

function [S,closedLoop] = motorResponse(num,den,kp,ki,kd)

    % Set up the transfer functions
    plant = tf(num,den);
    controller = pid(kp,ki,kd);
    
    % Feedback transfer function
    closedLoop = feedback(plant*controller,1);

    % Get the step response characteristics
    S = stepinfo(closedLoop);
    
end

